[CmdletBinding()]
param()
$ErrorActionPreference='Stop';$R='C:\TW\ComTW\runbooks\ssc-ollama-manual-scaling-01-phase1-20260829-210352';$E=Join-Path $R 'evidence';$C='C:\TW\ComTW\server\mangosd.conf';$M='C:\TW\ComTW\DB\bin\mariadb.exe';$S=Join-Path $E 'active-add-candidate-select.sql';$OutFile=Join-Path $E 'active-add-candidate-select.stdout.txt';$ErrFile=Join-Path $E 'active-add-candidate-select.stderr.txt';$J=Join-Path $E 'active-add-candidate-select.metadata.json';foreach($pathItem in @($S,$OutFile,$ErrFile,$J)){if(Test-Path $pathItem){throw "Refusing overwrite $pathItem"}}
function V($k){foreach($z in [IO.File]::ReadAllLines($C)){$t=$z.Trim();if(!$t-or$t.StartsWith('#')-or$t.StartsWith(';')){continue};$i=$t.IndexOf('=');if($i-gt 0-and$t.Substring(0,$i).Trim()-eq$k){return $t.Substring($i+1).Trim().Trim('"')}};throw "missing $k"}
$q=@"
SELECT c.guid,c.name,c.account,a.username,c.race,c.class,c.level,c.online,COALESCE(ev.add_value,0),COALESCE(ev.add_validIn,0),COALESCE(ev.login_value,0),IF(gm.memberGuid IS NULL,0,1),COALESCE(GROUP_CONCAT(CONCAT(cs.skill,':',cs.value,'/',cs.max) ORDER BY cs.skill SEPARATOR ','),'NONE') FROM tw_char.characters c JOIN tw_logon.account a ON a.id=c.account JOIN (SELECT bot,MAX(IF(event='add',value,0)) add_value,MAX(IF(event='add',validIn,0)) add_validIn,MAX(IF(event='login',value,0)) login_value FROM tw_char.ai_playerbot_random_bots WHERE owner=0 GROUP BY bot) ev ON ev.bot=c.guid LEFT JOIN tw_char.group_member gm ON gm.memberGuid=c.guid LEFT JOIN tw_char.character_skills cs ON cs.guid=c.guid AND cs.skill IN (164,165,171,182,186,197,202,333,393) WHERE a.username LIKE 'RNDBOT%' AND c.online=0 AND ev.add_value=1 AND ev.login_value=0 AND gm.memberGuid IS NULL GROUP BY c.guid,c.name,c.account,a.username,c.race,c.class,c.level,c.online,ev.add_value,ev.add_validIn,ev.login_value,gm.memberGuid ORDER BY COUNT(cs.skill) DESC,c.level DESC,c.guid LIMIT 25;
"@;[IO.File]::WriteAllText($S,$q,[Text.UTF8Encoding]::new($false));$d=(V 'LoginDatabase.Info')-split ';';$p=[Diagnostics.ProcessStartInfo]::new();$p.FileName=$M;$p.UseShellExecute=$false;$p.CreateNoWindow=$true;$p.RedirectStandardOutput=$true;$p.RedirectStandardError=$true;foreach($a in @('--no-defaults','--protocol=TCP','--skip-ssl','--connect-timeout=3','--batch','--raw','--skip-column-names',('--host='+$d[0]),('--port='+$d[1]),('--user='+$d[2]),('--execute='+$q))){[void]$p.ArgumentList.Add($a)};$p.Environment['MYSQL_PWD']=$d[3];$x=[Diagnostics.Process]::new();$x.StartInfo=$p;$st=[DateTime]::UtcNow;[void]$x.Start();$stdoutText=$x.StandardOutput.ReadToEnd();$stderrText=$x.StandardError.ReadToEnd();$x.WaitForExit();$stderrText=$stderrText-replace[regex]::Escape($d[3]),'<redacted>';[IO.File]::WriteAllText($OutFile,$stdoutText,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText($ErrFile,$stderrText,[Text.UTF8Encoding]::new($false));$m=[ordered]@{statement_class='SELECT only';sql_sha256=(Get-FileHash $S -Algorithm SHA256).Hash;started_utc=$st.ToString('o');finished_utc=[DateTime]::UtcNow.ToString('o');exit_code=$x.ExitCode;stdout_sha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($stdoutText)));stdout_size_bytes=[Text.Encoding]::UTF8.GetByteCount($stdoutText);stderr=$stderrText;database_writes=@()};[IO.File]::WriteAllText($J,($m|ConvertTo-Json)+"`n",[Text.UTF8Encoding]::new($false));$m|ConvertTo-Json;if($x.ExitCode-ne 0){exit $x.ExitCode}
